#!/usr/bin/env bash
# Docs « Mise en route » : installer Git, Node.js (nvm + .nvmrc) et Docker sur macOS, Linux et Windows
# (WSL 2), avec des onglets par système (composant OsTabs).
# Prérequis : apply-docs-mise-en-route.sh.
# Usage (racine du repo) : bash apply-docs-installation.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/demarrer/mise-en-route.mdx" 2>/dev/null | grep -qF "Windows : travailler dans WSL 2"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "Ce lanceur, à chaque appel" "apps/web/content/docs/dev/demarrer/mise-en-route.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-mise-en-route.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/demarrer/mise-en-route.mdx" "apps/web/src/mdx-components.tsx")
CREATED=(".nvmrc" "apps/web/src/features/docs/ui/OsTabs.tsx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "Windows : travailler dans WSL 2" "apps/web/content/docs/dev/demarrer/mise-en-route.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

base64 -d > ".nvmrc" <<'B64'
MjIK
B64
mkdir -p "apps/web/src/features/docs/ui"
